import{_ as e,C as o,o as r,c as i,aj as d,E as l}from"./framework.js";const g=JSON.parse('{"title":"邮箱 | Product | Documentation","description":"邮箱 in Kooboo: Kooboo 邮箱是账户级邮件工作台：日常收发邮件、维护邮箱地址和联系人、配置 IMAP/SMTP、查看 DMARC 报告，并为邮件扩展模块提供入口。","frontmatter":{"title":"邮箱 | Product | Documentation","description":"邮箱 in Kooboo: Kooboo 邮箱是账户级邮件工作台：日常收发邮件、维护邮箱地址和联系人、配置 IMAP/SMTP、查看 DMARC 报告，并为邮件扩展模块提供入口。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/product/mail.html"}]]},"headers":[],"relativePath":"zh/product/mail.md","filePath":"product/mail.md","lastUpdated":1786332863000}'),h={name:"zh/product/mail.md"};function m(s,t,c,n,b,p){const a=o("DocImage");return r(),i("div",null,[t[0]||(t[0]=d('<h1 id="邮箱" tabindex="-1">邮箱 <a class="header-anchor" href="#邮箱" aria-label="Permalink to &quot;邮箱&quot;">​</a></h1><blockquote><p>Kooboo 邮箱是账户级邮件工作台：日常收发邮件、维护邮箱地址和联系人、配置 IMAP/SMTP、查看 DMARC 报告，并为邮件扩展模块提供入口。</p></blockquote><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>顶部入口</td><td>点击顶部导航左侧的 <strong>邮箱</strong> 按钮</td></tr><tr><td>邮箱深链</td><td><code>/_Admin/kmail/inbox</code></td></tr><tr><td>设置深链</td><td><code>/_Admin/kmail-settings/addresses</code></td></tr><tr><td>前端路由</td><td><code>/kmail</code>、<code>/kmail-settings</code>、<code>/mail-module-editor</code></td></tr><tr><td>页面层级</td><td>账户 / 组织级页面，通常不带 <code>SiteId</code></td></tr></tbody></table><p>邮箱不是某个站点后台菜单。它更适合处理“哪些邮箱地址能收发信、谁是默认发件地址、如何给外部客户端生成授权码、邮件模块是否启用”这类账户级事项。若新增邮箱地址时看不到域名或页面提示邮箱不可用，先到 <a href="./console/domains.html">控制台：域名</a> 确认域名已经接入 Kooboo DNS。</p>',5)),l(a,{src:"/product/mail/mail-overview.png",alt:"邮箱概述：收件箱、地址分组与邮件列表",width:"1120"}),t[1]||(t[1]=d('<div class="tip custom-block"><p class="custom-block-title">菜单可见性</p><table tabindex="0"><thead><tr><th>身份 / 环境</th><th>可见入口</th></tr></thead><tbody><tr><td>组织成员</td><td>收件箱、已发送、草稿、垃圾邮件、已删除、邮箱地址、联系人、安全报告、IMAP</td></tr><tr><td>组织管理员</td><td>额外可见邮件扩展模块、Inbox Logo</td></tr><tr><td>组织管理员且非在线服务环境</td><td>额外可见 SMTP 设置</td></tr></tbody></table><p>前端路由中保留了 <code>/_Admin/kmail-settings/migration</code> 邮件迁移页，但当前左侧菜单默认注释隐藏。是否开放，以实际环境入口为准。</p></div><h2 id="邮箱主界面" tabindex="-1">邮箱主界面 <a class="header-anchor" href="#邮箱主界面" aria-label="Permalink to &quot;邮箱主界面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>菜单 / 入口</th><th>深链</th><th>文档</th><th>主要用途</th></tr></thead><tbody><tr><td>收件箱</td><td><code>/_Admin/kmail/inbox</code></td><td><a href="./mail/messages.html">邮件列表</a></td><td>查看收件、按地址筛选、标记已读、移动或删除邮件</td></tr><tr><td>已发送</td><td><code>/_Admin/kmail/sent</code></td><td><a href="./mail/messages.html">邮件列表</a></td><td>查看发出的邮件和投递状态</td></tr><tr><td>草稿</td><td><code>/_Admin/kmail/draft</code></td><td><a href="./mail/messages.html">邮件列表</a></td><td>继续编辑自动保存或手动保存的草稿</td></tr><tr><td>垃圾邮件</td><td><code>/_Admin/kmail/spam</code></td><td><a href="./mail/messages.html">邮件列表</a></td><td>查看 Spam，并可将邮件标记为非垃圾邮件</td></tr><tr><td>已删除</td><td><code>/_Admin/kmail/trash</code></td><td><a href="./mail/messages.html">邮件列表</a></td><td>恢复邮件或永久删除邮件</td></tr><tr><td>文件夹</td><td><code>/_Admin/kmail/folder</code></td><td><a href="./mail/messages.html#文件夹">邮件列表</a></td><td>使用自定义文件夹归档邮件</td></tr><tr><td>搜索结果</td><td><code>/_Admin/kmail/searchEmail</code></td><td><a href="./mail/messages.html#搜索邮件">邮件列表</a></td><td>从右上搜索框进入，按关键字查找邮件</td></tr><tr><td>日历</td><td><code>/_Admin/kmail/calendar</code></td><td><a href="./mail/calendar.html">日历</a></td><td>创建日程、邀请参与人、处理邮件会议邀请</td></tr><tr><td>写邮件</td><td><code>/_Admin/kmail/compose</code></td><td><a href="./mail/compose.html">撰写邮件</a></td><td>新建邮件、回复、全部回复、转发、再次编辑</td></tr></tbody></table><p>邮箱页面进入后会清除顶部邮箱红点，并每 5 分钟检查新邮件。若你正在收件箱，列表会尝试刷新并显示新邮件提示；若你在其它邮箱页，只显示新邮件提示。</p><h2 id="邮箱设置" tabindex="-1">邮箱设置 <a class="header-anchor" href="#邮箱设置" aria-label="Permalink to &quot;邮箱设置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>设置页</th><th>深链</th><th>文档</th><th>主要用途</th></tr></thead><tbody><tr><td>邮箱地址</td><td><code>/_Admin/kmail-settings/addresses</code></td><td><a href="./mail/addresses.html">邮箱地址</a></td><td>新建普通、通配、群组、转发地址，设置默认地址和签名</td></tr><tr><td>联系人</td><td><code>/_Admin/kmail-settings/contacts</code></td><td><a href="./mail/contacts.html">联系人</a></td><td>维护常用联系人</td></tr><tr><td>安全报告</td><td><code>/_Admin/kmail-settings/security-report</code></td><td><a href="./mail/security-report.html">安全报告</a></td><td>查看 DMARC 报告</td></tr><tr><td>IMAP</td><td><code>/_Admin/kmail-settings/imap-setting</code></td><td><a href="./mail/imap.html">IMAP</a></td><td>查看 IMAP/SMTP 客户端参数，生成授权码</td></tr><tr><td>邮件扩展模块</td><td><code>/_Admin/kmail-settings/mail-module</code></td><td><a href="./mail/modules.html">邮件扩展模块</a></td><td>创建、导入、安装、启停邮件模块，进入模块编辑器</td></tr><tr><td>Inbox Logo</td><td><code>/_Admin/kmail-settings/inbox-logo</code></td><td><a href="./mail/inbox-logo.html">Inbox Logo</a></td><td>配置 BIMI Logo 与 VMC URL</td></tr><tr><td>SMTP</td><td><code>/_Admin/kmail-settings/smtp-setting</code></td><td><a href="./mail/smtp.html">SMTP</a></td><td>在支持环境中配置自定义 SMTP</td></tr></tbody></table><h2 id="建议配置顺序" tabindex="-1">建议配置顺序 <a class="header-anchor" href="#建议配置顺序" aria-label="Permalink to &quot;建议配置顺序&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>顺序</th></tr></thead><tbody><tr><td>首次启用邮箱</td><td><a href="./console/domains.html">控制台：域名</a> -&gt; <a href="./mail/addresses.html">邮箱地址</a> -&gt; 设置默认地址 -&gt; <a href="./mail/imap.html">IMAP</a></td></tr><tr><td>让站点发送业务通知</td><td><a href="./mail/addresses.html">邮箱地址</a> -&gt; 设置默认发件地址 -&gt; <a href="/kb-docs/zh/api/mail/">k.mail</a> -&gt; 业务 API 或定时任务</td></tr><tr><td>日常处理邮件</td><td><a href="./mail/messages.html">邮件列表</a> -&gt; 搜索 / 文件夹 -&gt; <a href="./mail/compose.html">撰写邮件</a></td></tr><tr><td>接入外部客户端</td><td><a href="./mail/addresses.html">邮箱地址</a> -&gt; 设置默认地址 -&gt; <a href="./mail/imap.html">IMAP</a> -&gt; 生成授权码</td></tr><tr><td>扩展邮件工作流</td><td><a href="./mail/modules.html">邮件扩展模块</a> -&gt; 模块编辑器 -&gt; 启用模块 -&gt; 测试收发</td></tr><tr><td>安排邮件会议</td><td><a href="./mail/addresses.html">邮箱地址</a> -&gt; 设置默认地址 -&gt; <a href="./mail/calendar.html">日历</a> -&gt; 新建日程</td></tr></tbody></table><h2 id="与站点后台和-kscript-的分工" tabindex="-1">与站点后台和 KScript 的分工 <a class="header-anchor" href="#与站点后台和-kscript-的分工" aria-label="Permalink to &quot;与站点后台和 KScript 的分工&quot;">​</a></h2><table tabindex="0"><thead><tr><th>邮箱后台做</th><th>站点后台 / KScript 做</th></tr></thead><tbody><tr><td>配置邮箱地址、默认发件地址、签名、IMAP 授权码</td><td>在站点 API、Job、Hook 中使用 <a href="/kb-docs/zh/api/mail/">k.mail</a> 发信或收信</td></tr><tr><td>管理邮件列表、文件夹、联系人和 DMARC 报告</td><td>在业务流程中决定什么时候发邮件、发给谁、记录什么日志</td></tr><tr><td>管理邮件扩展模块和模块文件</td><td>模块内部脚本细节参考 <a href="/kb-docs/zh/api/mail/">k.mail</a> 与 <a href="/kb-docs/zh/api/module/">模块 API</a></td></tr><tr><td>配置账户级 SMTP 或 Inbox Logo</td><td>站点后台继续配置内容、页面、服务集成、AI 服务等站点级能力</td></tr></tbody></table><p>产品文档只说明后台入口、表单和保存方式；KScript 函数签名与脚本示例请看 <a href="/kb-docs/zh/api/">API 文档</a>。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="/kb-docs/zh/api/mail/">k.mail</a></td><td>KScript 邮件 API</td></tr><tr><td><a href="./console.html">控制台</a></td><td>域名、余额与组织</td></tr><tr><td><a href="/kb-docs/zh/cms/settings/integrations/">CMS：服务集成</a></td><td>站点级第三方服务配置</td></tr></tbody></table>',13))])}const _=e(h,[["render",m]]);export{g as __pageData,_ as default};
